lib='''from collections import deque

def neighbors(r, c, h, w):
    """The 4-adjacent in-bounds cells of (r, c)."""
    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
        nr, nc = r+dr, c+dc
        if 0 <= nr < h and 0 <= nc < w:
            yield nr, nc

def flood_bg(grid, bg):
    """Mark every cell of color bg reachable from the border."""
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    q = deque()
    for i in range(h):
        for j in (0, w-1):
            if grid[i][j] == bg and not seen[i][j]:
                seen[i][j] = True; q.append((i, j))
    for j in range(w):
        for i in (0, h-1):
            if grid[i][j] == bg and not seen[i][j]:
                seen[i][j] = True; q.append((i, j))
    while q:
        r, c = q.popleft()
        for nr, nc in neighbors(r, c, h, w):
            if grid[nr][nc] == bg and not seen[nr][nc]:
                seen[nr][nc] = True; q.append((nr, nc))
    return seen

def enclosed_components(grid, bg=None):
    """Components of color bg (default: the corner color) not reachable from the border."""
    if bg is None: bg = grid[0][0]
    h, w = len(grid), len(grid[0])
    reach = flood_bg(grid, bg)
    comps, seen = [], [[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg and not reach[i][j] and not seen[i][j]:
                comp, q = [], deque([(i, j)])
                seen[i][j] = True
                while q:
                    r, c = q.popleft(); comp.append((r, c))
                    for nr, nc in neighbors(r, c, h, w):
                        if grid[nr][nc] == bg and not reach[nr][nc] and not seen[nr][nc]:
                            seen[nr][nc] = True; q.append((nr, nc))
                comps.append(comp)
    return comps

def is_rectangle(cells):
    """Whether a cell set is a full solid axis-aligned rectangle."""
    rs = [r for r, c in cells]; cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    return len(cells) == (r1-r0+1)*(c1-c0+1)

def fill_rect_holes(grid, fill=4):
    """Enclosed background regions that are solid rectangles become fill; other shapes keep their color."""
    g = [row[:] for row in grid]
    for comp in enclosed_components(g):
        if is_rectangle(comp):
            for r, c in comp: g[r][c] = fill
    return g
